const $=s=>document.querySelector(s);const $$=s=>[...document.querySelectorAll(s)];let method='card',declines=0,recoveries=0,timer=null,seconds=598;const state={events:[]};
function event(name,data={}){state.events.unshift({name,data,time:new Date().toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit',second:'2-digit'})});renderEvents()}
function renderEvents(){const log=$('#eventLog');log.innerHTML=state.events.length?state.events.map(e=>`<div class="event"><b>${e.name}</b><span>${e.time}</span><br>${Object.entries(e.data).map(([k,v])=>`${k}: ${v}`).join(' · ')||'—'}</div>`).join(''):'<p class="empty">Interaja com o checkout para gerar eventos.</p>';$('#declines').textContent=declines;$('#recoveries').textContent=recoveries;$('#rate').textContent=declines?Math.round(recoveries/declines*100)+'%':'0%'}
function toast(text){const el=$('#toast');el.textContent=text;el.classList.remove('hidden');setTimeout(()=>el.classList.add('hidden'),2600)}
function selectMethod(next){method=next;$$('.tab').forEach(t=>t.classList.toggle('active',t.dataset.method===next));const fields=$('#cardFields'),alt=$('#altMethod');if(next==='card'){fields.classList.remove('hidden');alt.classList.add('hidden');$('#payButton span').textContent='Finalizar compra'}else{fields.classList.add('hidden');alt.classList.remove('hidden');alt.innerHTML=next==='pix'?'<strong>Pix: aprovação em poucos segundos</strong><p>O QR Code será exibido após confirmar o pedido.</p>':'<strong>Boleto bancário</strong><p>O código de barras será gerado com vencimento amanhã.</p>';$('#payButton span').textContent=next==='pix'?'Gerar QR Code Pix':'Gerar boleto'}}
function openRecovery(){declines++;event('payment_declined',{method:'creditCard',reason_code:'51',order_form_id:'142938'});$('#recoveryBackdrop').classList.remove('hidden');$('#recoveryModal').classList.remove('hidden');$('#chatBadge').classList.remove('hidden');event('recovery_modal_view',{variant:'modal_v1'});seconds=598;clearInterval(timer);timer=setInterval(()=>{seconds--;$('#countdown').textContent=String(Math.floor(seconds/60)).padStart(2,'0')+':'+String(seconds%60).padStart(2,'0');if(seconds<=0)clearInterval(timer)},1000)}
function closeRecovery(){clearInterval(timer);$('#recoveryBackdrop').classList.add('hidden');$('#recoveryModal').classList.add('hidden')}
function recover(next){event('recovery_option_selected',{option:next});closeRecovery();selectMethod(next==='retry'?'card':next);recoveries++;renderEvents();toast(next==='pix'?'Pix selecionado — pedido preservado':next==='boleto'?'Boleto selecionado — pedido preservado':'Você pode informar um novo cartão');event('checkout_recovered',{new_method:next})}
function openChat(){closeRecovery();$('#chatPanel').classList.remove('hidden');$('#chatLauncher').classList.add('hidden');$('#chatBadge').classList.add('hidden');event('recovery_chat_open',{source:'checkout'})}
function botReply(text){const m=$('#messages');m.insertAdjacentHTML('beforeend',`<div class="bot-msg">${text}<time>agora</time></div>`);m.scrollTop=m.scrollHeight}
$$('.tab').forEach(t=>t.addEventListener('click',()=>{selectMethod(t.dataset.method);event('payment_method_selected',{method:t.dataset.method})}));
$('#paymentForm').addEventListener('submit',e=>{e.preventDefault();const btn=$('#payButton');btn.disabled=true;btn.querySelector('span').textContent='Recebendo retorno da VTEX...';setTimeout(()=>{btn.disabled=false;if(method==='card'){btn.querySelector('span').textContent='Simular recusa do pagamento';openRecovery()}else{recoveries++;event('payment_approved',{method});toast(method==='pix'?'QR Code Pix gerado com sucesso':'Boleto gerado com sucesso');btn.querySelector('span').textContent=method==='pix'?'Pix gerado ✓':'Boleto gerado ✓';renderEvents()}},1100)});
$$('[data-close]').forEach(b=>b.addEventListener('click',closeRecovery));$('#recoveryBackdrop').addEventListener('click',closeRecovery);$$('[data-action]').forEach(b=>b.addEventListener('click',()=>recover(b.dataset.action)));$('#talkNow').addEventListener('click',openChat);$('#chatLauncher').addEventListener('click',openChat);$('[data-chat-close]').addEventListener('click',()=>{$('#chatPanel').classList.add('hidden');$('#chatLauncher').classList.remove('hidden')});
$$('[data-chat-action]').forEach(b=>b.addEventListener('click',()=>{const a=b.dataset.chatAction;event('chat_quick_reply',{reply:a});if(a==='pix'){botReply('Perfeito! Selecionei Pix para você. Clique em “Gerar QR Code Pix” para concluir.');selectMethod('pix');recoveries++;renderEvents()}else if(a==='card'){botReply('Sem problema. Feche este chat e informe os dados do outro cartão. Seu pedido continua reservado.');selectMethod('card')}else botReply('Certo! Estou chamando uma pessoa do nosso time. O tempo médio de resposta é de 1 minuto.')}));
$('#chatForm').addEventListener('submit',e=>{e.preventDefault();const input=$('#chatInput');if(!input.value.trim())return;$('#messages').insertAdjacentHTML('beforeend',`<div class="user-msg">${input.value.replace(/[<>]/g,'')}<time>agora</time></div>`);event('chat_message_sent');input.value='';setTimeout(()=>botReply('Entendi. Posso manter seu pedido reservado enquanto ajudamos você com o pagamento.'),500)});
$('#openMetrics').addEventListener('click',()=>$('#metricsPanel').classList.remove('hidden'));$('[data-metrics-close]').addEventListener('click',()=>$('#metricsPanel').classList.add('hidden'));$('#clearEvents').addEventListener('click',()=>{state.events=[];declines=0;recoveries=0;renderEvents()});
event('checkout_view',{step:'payment',device:innerWidth<790?'mobile':'desktop'});
